export const ADHKAR_TEXT_KEYS=Object.freeze({...Object.fromEntries(Object.entries(ADHKAR_UI_SOURCE).filter(([,value])=>!value.includes('{')).map(([key,value])=>[value,'adhkarUi.'+key])),Азкары:'nav.adhkar','Утренние азкары':'home.morningAdhkar','Вечерние азкары':'home.eveningAdhkar',Повторить:'common.retry',Закрыть:'common.close',Отмена:'common.cancel',Назад:'common.back'});
export const adhkarGroupKey=group=>({morning:'home.morningAdhkar',evening:'home.eveningAdhkar',all:'adhkarUi.allDhikr',favorites:'adhkarUi.favorites'}[group]||null);
export function adhkarGroupLabel(group,fallback=''){const key=adhkarGroupKey(group);return key?uiMessage(key,fallback):fallback;}
export function adhkarGroupLeaf(group,fallback=''){const key=adhkarGroupKey(group);return key?uiLeaf(key,fallback):esc(fallback);}
